package com.tradingplatform.persistence;
import com.tradingplatform.paper.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="paper_positions") public class PaperPositionEntity { @Id public UUID id; @Column(name="account_id") public UUID accountId; @Column(name="instrument_key") public String instrumentKey; public String symbol,exchange; @Enumerated(EnumType.STRING) public PaperSide side; public int quantity; @Column(name="average_entry_price") public BigDecimal averageEntryPrice; @Column(name="current_price") public BigDecimal currentPrice; @Column(name="unrealized_pnl") public BigDecimal unrealizedPnl; @Column(name="realized_pnl") public BigDecimal realizedPnl; @Column(name="stop_loss") public BigDecimal stopLoss; public BigDecimal target; @Enumerated(EnumType.STRING) public PaperPositionStatus status; @Column(name="opened_at") public Instant openedAt; @Column(name="updated_at") public Instant updatedAt; }
